import HomeIcon from "@mui/icons-material/Home";
import SearchIcon from "@mui/icons-material/Search";
import MessageIcon from "@mui/icons-material/Message";
import PersonIcon from "@mui/icons-material/Person";
import ShoppingCartIcon from "@mui/icons-material/ShoppingCart";
import CloseIcon from "@mui/icons-material/Close";
import CalendarMonthIcon from "@mui/icons-material/CalendarMonth";  // Changed back to CalendarMonthIcon
import { useNavigate } from "react-router-dom";

interface NavigationBarProps {
  onSelect?: (page: string) => void;
  activePage: number;
  onHomeClick: () => void;  // Add onHomeClick prop
}

export default function NavigationBar({ onSelect, activePage, onHomeClick }: NavigationBarProps) {
  const [searchOpen, setSearchOpen] = React.useState(false);
  const [searchQuery, setSearchQuery] = React.useState("");
  const [selectedDate, setSelectedDate] = React.useState<string | null>(null);

  const navRef = React.useRef<HTMLDivElement | null>(null);

  const menuItems = [
    { label: "Home", value: "home" },
    { label: "Venues", value: "venues" },
    { label: "Caterers", value: "caterers" },
    { label: "Hair", value: "hair" },
    { label: "Makeup", value: "makeup" },
    { label: "Photographers", value: "photographers" },
    { label: "Music", value: "music" },
    { label: "Florist", value: "florist" },
    { label: "Dresser", value: "dresser" },
    { label: "Planner", value: "planner" },
  ];

  React.useEffect(() => {
    const storedDate = localStorage.getItem("selectedDate");
    if (storedDate) {
      setSelectedDate(storedDate);
    }
  }, []);

  const handleMenuItemClick = (index: number) => {
    if (onSelect) {
      onSelect(menuItems[index].value);
    }

    if (navRef.current) {
      const selectedButton = navRef.current.children[index] as HTMLElement;
      if (selectedButton) {
        navRef.current.scrollTo({
          left:
            selectedButton.offsetLeft -
            navRef.current.offsetWidth / 2 +
            selectedButton.offsetWidth / 2,
          behavior: "smooth",
        });
      }
    }
  };

  const handleDateClick = () => {
    // Navigate to calendar page if needed
  };

  const handleLogoClick = () => {
    handleMenuItemClick(0);
  };

  const handleCartClick = () => {
    // Navigate to cart page if needed
  };

  return (
    <>
      <AppBar
        position="fixed"
        color="transparent"
        elevation={0}
        sx={{
          top: 0,
          zIndex: 1200,
          backgroundColor: "transparent",
          backdropFilter: "blur(10px)",
        }}
      >
        <Toolbar sx={{ display: "flex", alignItems: "center", paddingX: 4 }}>
          <Avatar
            sx={{
              width: 40,
              height: 40,
              bgcolor: "#a58b84",
              marginRight: 2,
              cursor: "pointer",
            }}
            onClick={handleLogoClick}
          >
            E
          </Avatar>

          <Typography
            variant="h6"
            sx={{
              fontWeight: "bold",
              textTransform: "uppercase",
              cursor: "pointer",
              flexGrow: 1,
              textAlign: "center",
              color: "#000",
              display: "flex",
              alignItems: "center",
              marginLeft: "20px",  // Slight move to the right for better centering
            }}
            onClick={handleDateClick}
          >
            <CalendarMonthIcon sx={{ marginRight: 1, color: "#6B4F4F" }} />
            <span
              style={{
                color: "#6B4F4F", // Same color for the text
                cursor: "pointer",
              }}
            >
              {selectedDate || "Select Date"}
            </span>
          </Typography>

          <IconButton color="inherit" onClick={handleCartClick}>
            <ShoppingCartIcon sx={{ fontSize: "32px", color: "#5a3c3c" }} />
          </IconButton>
        </Toolbar>
      </AppBar>

      {/* Bottom Navigation Bar */}
      <AppBar
        position="fixed"
        sx={{
          top: "auto",
          bottom: 0,
          left: 0,
          right: 0,
          backgroundColor: "#fff",
          boxShadow: "0px -2px 5px rgba(0, 0, 0, 0.1)",
          height: "60px",
          zIndex: 1300,
        }}
      >
        <Toolbar sx={{ display: "flex", justifyContent: "space-around" }}>
          <IconButton sx={{ color: "#000" }} onClick={onHomeClick}> {/* Added onHomeClick here */}
            <HomeIcon />
          </IconButton>
          <IconButton sx={{ color: "#000" }}>
            <SearchIcon />
          </IconButton>
          <IconButton sx={{ color: "#000" }}>
            <MessageIcon />
          </IconButton>
          <IconButton sx={{ color: "#000" }}>
            <PersonIcon />
          </IconButton>
        </Toolbar>
      </AppBar>
    </>
  );
}
